 52	                                                                Environment envForInference) throws ProgramError {
 53	
 54	        if (DUMP_INFERENCE) System.err.println("IAIGF " + appliedThing + " with " + args);
 55	
 56	        GenericTypeInstance selfType = null; // initialized if generic functional method
