 64	            if (selfArg.type() instanceof GenericTypeInstance) {
 65	                selfType = (GenericTypeInstance) selfArg.type();
 66	                // Find the supertype that exactly matches "self"
 67	                for (FType ft : selfType.getTransitiveExtends()) {
 68	                    if (ft instanceof GenericTypeInstance && ((GenericTypeInstance) ft).getGeneric().equals(
 69	                            declaredSelfType)) {
 70	                        selfType = (GenericTypeInstance) ft;
 71	                        break;
 72	                    }
 73	                }
 74	                envForInference = selfType.getWithin();
 75	            } else return error(errorMsg("Non-generic-instance type for self argument ",
 76	                                         selfArg,
