 85	        EvalType et = new EvalType(appliedThing.getWithin());// e);
 86	        // The types of the actual parameters ought to unify with the
 87	        // types of the formal parameters.
 88	        BoundingMap<String, FType, TypeLatticeOps> abm = new
 89	                // ABoundingMap
 90	                LatticeIntervalMap<String, FType, TypeLatticeOps>(TypeLatticeOps.V, DefaultComparator.V);
 91	        Param p = null;
 92	        Set<String> tp_set = new HashSet<String>();
 93	        List<StaticParam> rechecks = null;
 94	        for (StaticParam sp : tparams) {
 95	            boolean rechecked = false;
 96	            String name = NodeUtil.getName(sp);
 97	            tp_set.add(name);
 98	            if (NodeUtil.isTypeParam(sp)) {
 99	                if (DUMP_INFERENCE) System.err.println("TypeParam " + sp);
100	                for (Type tr : sp.getExtendsClause()) {
101	                    // Preinstall bounds in the boundingmap
102	                    try {
103	                        FType tt = et.evalType(tr);
104	                        if (DUMP_INFERENCE) System.err.println("    extends " + tr + " = " + tt);
105	                        abm.meetPut(name, tt);
106	                    }
107	                    catch (FortressException pe) {
108	                        if (DUMP_INFERENCE) System.err.println("    extends with failed evalType " + tr);
109	                        if (!rechecked) {
110	                            rechecked = true;
111	                            if (rechecks == null) {
112	                                rechecks = new ArrayList<StaticParam>();
113	                            }
114	                            rechecks.add(sp);
115	                        }
116	                    }
117	                }
118	            } else if (DUMP_INFERENCE) System.err.println("Non-simple StaticParam " + sp);
119	        }
120	        /* FIX FOR #62 */
121	        if (params.size() == 1 && args.size() != 1) {
122	            Iterator<Param> pit = params.iterator();
123	            Param pa = pit.next();
124	
125	            if (!NodeUtil.isVarargsParam(pa)) {
126	                /* Tuple (or even re-tuple) arguments when inferring type
127	                 * if passing different # of args to 1-arg function. */
128	                if (DUMP_INFERENCE) {
129	                    System.err.println("Tupling args to match single-arg context.");
130	                }
131	                args = Useful.<FValue>list(FTuple.make(args));
132	            }
133	        }
134	        Iterator<Param> pit = params.iterator();
135	        for (FValue a : args) {
136	            FType at = a.type();
137	            if (at == null) {
138	                if (DUMP_INFERENCE) System.err.println("Argument " + a + " without type info.");
139	                return error(errorMsg("Argument ", a, " has no type information"));
140	            }
141	            if (pit.hasNext()) {
142	                p = pit.next();
143	            } else if (p == null) {
144	                if (DUMP_INFERENCE) System.err.println("Arguments " + args + " to 0-arg function.");
145	                error(errorMsg(" Arguments ", args, " given to 0-argument generic function ", appliedThing));
146	            }
147	            try {
148	                if (!NodeUtil.isVarargsParam(p)) {
149	                    Option<TypeOrPattern> t = p.getIdType();
150	                    // why can't we just skip if missing?
151	                    if (t.isNone()) {
152	                        /*
153	                         * Fake the type for a generic functional method
154	                         * invocation.
155	                         */
156	                        if (p.getName().toString().equals("self") && appliedThing instanceof GenericFunctionalMethod) {
157	                            // Use precomputed selfType that will match declared
