812	    /**
813	     * For args that no overload takes without coercion: the most specific of
814	     * the non-generic overloads applicable with coercion, as a call that
815	     * converts its arguments first and then dispatches the converted
816	     * arguments as an ordinary call; or null.  The coercions depend only on
817	     * the argument types, so the call may be kept in the per-argument-type
818	     * cache.  It is an error when no one of them is more specific than all
819	     * the others.
820	     */
821	    private SingleFcn bestMatchWithCoercion(List<FValue> args, List<Overload> someOverloads) {
822	        Coercions.CoercedCall best = null;
823	        List<Coercions.CoercedCall> applicable = new ArrayList<Coercions.CoercedCall>();
824	        for (Overload o : someOverloads) {
825	            SingleFcn sfn = o.getFn();
826	            if (sfn instanceof GenericFunctionOrMethod) continue;
827	            List<FValue> oargs = sfn.fixupArgCount(args);
828	            if (oargs == null) continue;
829	            List<FType> domain = sfn.getDomain();
830	            SingleFcn[] coercions = new SingleFcn[oargs.size()];
831	            boolean applies = true;
832	            for (int j = 0; applies && j < oargs.size(); j++) {
833	                FType t = Useful.clampedGet(domain, j).deRest();
834	                FValue a = oargs.get(j);
835	                if (!argsMatchTypes(Collections.singletonList(a), Collections.singletonList(t))) {
836	                    coercions[j] = Coercions.coercionFor(t, a);
837	                    applies = coercions[j] != null;
838	                }
839	            }
840	            if (!applies) continue;
841	            Coercions.CoercedCall c = new Coercions.CoercedCall(sfn, coercions, this);
842	            applicable.add(c);
843	            if (best == null || Coercions.moreSpecific(domain, best.getDomain(), oargs.size())) best = c;
844	        }
845	        for (Coercions.CoercedCall c : applicable) {
846	            if (c != best && !Coercions.moreSpecific(best.getDomain(), c.getDomain(), best.arity())) {
847	                return error(errorMsg("Ambiguous coercion, args = ",
848	                                      Useful.listInParens(args),
849	                                      ", applicable with coercion = ",
850	                                      Useful.listInDelimiters("{", applicable, "}")));
851	            }
852	        }
853	        return best;
854	    }
