 33	    /**
 34	     * The lifted coercions to target, or null when target declares none.
 35	     */
 36	    private static Fcn liftedCoercions(FType target) {
 37	        if (!(target instanceof FTraitOrObject)) return null;
 38	        Environment e = target.getWithin();
 39	        if (e == null) return null;
 40	        FValue f = e.getTopLevel().getRootValueNull(NamingCzar.LIFTED_COERCION_PREFIX + target.getName());
