 44	    /**
 45	     * The coercion to target that applies to v without a coercion (coercions
 46	     * do not chain), or null.
 47	     */
 48	    static SingleFcn coercionFor(FType target, FValue v) {
 49	        Fcn lifted = liftedCoercions(target);
 50	        if (lifted == null) return null;
 51	        List<FValue> args = Collections.singletonList(v);
 52	        if (lifted instanceof OverloadedFunction) {
 53	            return ((OverloadedFunction) lifted).bestMatchWithoutCoercion(args);
 54	        }
 55	        SingleFcn f;
 56	        if (lifted instanceof GenericFunctionOrMethod) {
 57	            GenericFunctionOrMethod g = (GenericFunctionOrMethod) lifted;
 58	            try {
 59	                f = EvaluatorBase.inferAndInstantiateGenericFunction(args, g, g.getWithin());
 60	            }
 61	            catch (FortressException ex) {
 62	                return null;
 63	            }
 64	        } else if (lifted instanceof SingleFcn) {
 65	            f = (SingleFcn) lifted;
 66	        } else {
 67	            return null;
 68	        }
 69	        List<FValue> fargs = f.fixupArgCount(args);
 70	        return fargs != null && OverloadedFunction.argsMatchTypes(fargs, f.getDomain()) ? f : null;
 71	    }
