 99	    private static FValue coerceTuple(FTypeTuple target, FValue v) {
100	        if (!(v instanceof FTuple)) return null;
101	        List<FType> types = target.getTypes();
102	        List<FValue> vals = ((FTuple) v).getVals();
103	        if (types.size() != vals.size()) return null;
104	        List<FValue> converted = new ArrayList<FValue>(vals.size());
105	        for (int j = 0; j < types.size(); j++) {
106	            FType t = types.get(j);
107	            if (t instanceof FTypeRest) return null;
108	            FValue e = vals.get(j);
109	            if (!t.typeMatch(e)) {
110	                e = coerce(t, e);
111	                if (e == null) return null;
112	            }
113	            converted.add(e);
114	        }
115	        return FTuple.make(converted);
