159	    /**
160	     * t is no less specific than u: t is a subtype of u, or t excludes, can be
161	     * coerced to, and rejects u.
162	     */
163	    private static boolean noLessSpecific(FType t, FType u) {
164	        if (t.subtypeOf(u)) return true;
165	        if (!t.excludesOther(u)) return false;
166	        boolean coercesTo = false;
167	        for (FType a : coercionSources(u)) {
168	            if (t.subtypeOf(a)) coercesTo = true;
169	        }
170	        if (!coercesTo) return false;
171	        for (FType a : coercionSources(t)) {
172	            if (!a.excludesOther(u)) return false;
173	        }
174	        return true;
175	    }
