181	    static boolean moreSpecific(List<FType> c, List<FType> d, int n) {
182	        boolean differ = false;
183	        for (int j = 0; j < n; j++) {
184	            FType t = Useful.clampedGet(c, j).deRest();
185	            FType u = Useful.clampedGet(d, j).deRest();
186	            if (!noLessSpecific(t, u)) return false;
187	            if (t != u) differ = true;
188	        }
189	        return differ;
