350	    public Set<FType> join(FType t2) {
351	        if (this.equals(t2)) {
352	            return Useful.set(this);
353	        } else if (t2.subtypeOf(this)) {
354	            // Join of x with dynamic is X.
355	            return Useful.set(this);
356	        } else if (this.subtypeOf(t2)) {
357	            return Useful.set(t2);
358	        } else {
359	            Set<FType> result = Collections.emptySet();
360	            for (FType candidate : getTransitiveExtends()) {
361	                if (!t2.subtypeOf(candidate)) continue;
362	                TreeSet<FType> newresult = new TreeSet<FType>();
363	                boolean addC = true;
364	                for (FType r : result) {
365	                    if (r.subtypeOf(candidate)) {
366	                        addC = false;
367	                        break;
368	                    } else if (candidate.subtypeOf(r)) {
369	                        /* Drop r */
370	                    } else {
371	                        newresult.add(r);
372	                    }
373	                }
374	                if (addC) {
375	                    newresult.add(candidate);
376	                    result = newresult;
377	                }
378	            }
379	            return result;
380	        }
381	    }
