391	    public static Set<FType> joinTypes(List<FType> types) {
392	        // A is the accumulated set of joined items.
393	        Set<FType> a = null;
394	        if (types.size() > 0) {
395	            for (FType vt : types) {
396	                // for each value, join in the value's type.
397	                TreeSet<FType> b = new TreeSet<FType>();
398	                if (a == null) {
399	                    b.add(vt);
400	                } else {
401	                    // For each type in the accumulator, do the
402	                    // join with the next element, accumulating in b.
403	                    for (FType t : a) {
404	                        b.addAll(t.join(vt));
405	                    }
406	                }
407	                a = b;
408	            }
409	            // Now a may contain non-minimal types.
410	            if (a.size() > 1) {
411	                TreeSet<FType> r = new TreeSet<FType>();
412	                for (FType c : a) {
413	                    if (r.size() == 0) {
414	                        r.add(c);
415	                    } else {
416	                        boolean addC = true;
417	                        TreeSet<FType> s = new TreeSet<FType>();
418	                        for (FType d : r) {
419	                            if (c.subtypeOf(d)) {
420	                                /* Drop d */
421	                            } else if (d.subtypeOf(c)) {
422	                                addC = false;
423	                                s = r;
424	                                break;
425	                            } else {
426	                                s.add(d);
427	                            }
428	                        }
429	                        if (addC) s.add(c);
430	                        r = s;
431	                    }
432	                }
433	                a = r;
434	            }
435	        } else {
436	            // Empty set, best we can do
437	            a = FTypeTop.SingleSet; // why isn't this a real empty set?
438	        }
439	        return a;
440	    }
